Lemma aacc_last (M : word -> option byte) p n : 0 < n -> aacc M p n ->
  exists k, byte_at M (0x7fff8000 + (p + n - 1) / 8) k /\ (k = 0 \/ (p + n - 1) mod 8 < k <= 7).
Proof.
